buckets = (input or {}).get('buckets') or {}
low = [b for b, v in buckets.items() if (v or {}).get('remaining') is not None and v['remaining'] < 25]
output = {'ok': not low, 'low_buckets': low, 'reason': 'Starting a review that cannot finish leaves a half read population that looks complete.' if low else 'Enough headroom to finish.'}

pack = input or {}
changes = (pack.get('access_changes') or {})
counts = changes.get('counts') or {}
ungoverned = counts.get('ungoverned', 0)
system = counts.get('system', 0)
governed = counts.get('governed', 0)
if ungoverned:
    verdict = 'contested'
    why = str(ungoverned) + ' access changes were visible with no governed approval behind them.'
elif governed and not system:
    verdict = 'governed'
    why = 'Every visible access change was made through the module.'
elif governed or system:
    verdict = 'partial'
    why = ('Visible changes are governed or Okta system originated, with none ungoverned. ' if governed else 'Every visible change is Okta system originated. ') + 'Okta attributes some console actions to its own system principal, so this is not proof that no person acted.'
else:
    verdict = 'unproven'
    why = 'No access change was visible in the window read. That is not evidence that none occurred.'
output = {'custody': verdict, 'why': why, 'log_watermark': pack.get('log_watermark'), 'log_read_complete': pack.get('log_read_complete'), 'bounded_by': 'Okta publishes no maximum System Log delivery latency, so every statement above is bounded by the watermark and never claims absence.'}
